const express = require("express");
const router = express.Router();

router.get("/", (req, res) => {
    res.json({ mensagem: "Lista de livros" });
});

module.exports = router;

// src/controllers/livroController.js
const livroService = require("../services/livroService");

async function listar(req, res) {
    try {
        const livros = await livroService.listarLivros();
        res.json(livros);
    } catch (erro) {
        res.status(500).json({ erro: "Erro ao consultar livros." });
    }
}

async function cadastrar(req, res) {
    try {
        const livro = await livroService.cadastrarLivro(req.body);
        res.status(201).json(livro);
    } catch (erro) {
        res.status(400).json({ erro: erro.message });
    }
}

module.exports = { listar, cadastrar };

